'use client';

import React, { useRef, useEffect } from 'react';
import * as THREE from 'three';

interface SubstrateProps {
  tankBounds: THREE.Vector3;
  substrateConfig: {
    name: string;
    color: string;
    roughness: number;
    metalness: number;
  } | null;
  substrateKg: number;
  onHeightCalculated: (height: number) => void;
}

export default function Substrate({ tankBounds, substrateConfig, substrateKg, onHeightCalculated }: SubstrateProps) {
  const meshRef = useRef<THREE.Mesh>(null);

  const baseTankBottom = -tankBounds.y / 2;
  const calculatedHeight = (!substrateConfig || substrateKg <= 0) 
    ? 0.35 
    : Math.min(Math.max(substrateKg * 0.04, 0.1), 2.5);

  useEffect(() => {
    const absoluteBottomY = baseTankBottom + calculatedHeight;
    onHeightCalculated(absoluteBottomY);

    if (!meshRef.current || !substrateConfig) return;
    const geometry = meshRef.current.geometry as THREE.PlaneGeometry;
    const posAttribute = geometry.attributes.position;

    // Doğal, engebeli dalga formülasyonu
    for (let i = 0; i < posAttribute.count; i++) {
      const x = posAttribute.getX(i);
      const y = posAttribute.getY(i);
      const wave = Math.sin(x * 0.7) * Math.cos(y * 0.7) * (calculatedHeight * 0.35);
      posAttribute.setZ(i, wave);
    }
    posAttribute.needsUpdate = true;
    geometry.computeVertexNormals();
  }, [calculatedHeight, substrateConfig, baseTankBottom, onHeightCalculated]);

  if (!substrateConfig || substrateKg <= 0) return null;

  return (
    <group position={[0, baseTankBottom, 0]}>
      <mesh ref={meshRef} rotation={[-Math.PI / 2, 0, 0]} position={[0, calculatedHeight / 2, 0]} receiveShadow>
        <planeGeometry args={[tankBounds.x, tankBounds.z, 64, 64]} />
        <meshStandardMaterial
          color={substrateConfig.color}
          roughness={substrateConfig.roughness}
          metalness={substrateConfig.metalness}
          flatShading={false}
          side={THREE.DoubleSide}
        />
      </mesh>
    </group>
  );
}