'use client';

import React from 'react';
import * as THREE from 'three';

interface PlantFieldProps {
  tankBounds: THREE.Vector3;
  plantsConfig?: any[];
}

export default function PlantField({ tankBounds, plantsConfig = [] }: PlantFieldProps) {
  // İleride burası config üzerinden gelen bitki modellerini dinamik olarak sahneye dikecek.
  // Şu an için akvaryum tamamen saf ve temiz tutuluyor.
  return (
    <group>
      {plantsConfig.map((plant, index) => (
        <group key={plant.id || index} position={plant.position || [0, 0, 0]}>
          {/* Dinamik bitki yerleşimi buraya gelecek */}
        </group>
      ))}
    </group>
  );
}