import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import * as SkeletonUtils from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface FishPhysicsConfig {
  minSpeed: number;
  maxSpeed: number;
  diveInterval: number;
  verticalFreedom: number;
  turnSpeed: number;
}

export interface SwimShaderConfig {
  bodySpeed?: number;
  bodyFreq?: number;
  bodyAmp?: number;
  finSpeed?: number;
  pectoralAmp?: number;
  caudalWhip?: number;
}

export interface FishAppearanceConfig {
  color?: string;
  roughness?: number;
  metalness?: number;
}

export interface FishConfig {
  id: string;
  name: string;
  modelPath: string;
  texturePath?: string;
  count?: number;
  appearance?: FishAppearanceConfig;
  behavior?: 'normal' | 'bottom_dweller';
  physics: FishPhysicsConfig;
  swimShader: SwimShaderConfig;
}

interface FishInstance {
  model: THREE.Object3D;
  velocity: THREE.Vector3;
  targetVelocity: THREE.Vector3;
  speed: number;
  config: FishConfig;
  preferredDepth: number;
  timer: number;
  tail?: THREE.Object3D;
  finLBig?: THREE.Object3D;
  finRBig?: THREE.Object3D;
}

interface LoadedTemplate {
  model: THREE.Object3D;
  config: FishConfig;
}

export class FishManager {
  private scene: THREE.Scene;
  private bounds: THREE.Vector3;
  private templates: Map<string, LoadedTemplate> = new Map();
  private fishList: FishInstance[] = [];
  private loader!: GLTFLoader;
  private textureLoader: THREE.TextureLoader;
  private targetGroundLevel: number;
  private currentGroundLevel: number;
  
  private eyeIrisMaterial: THREE.MeshBasicMaterial;
  private pupilMaterial: THREE.MeshBasicMaterial;

  constructor(scene: THREE.Scene, tankBounds: THREE.Vector3) {
    this.scene = scene;
    this.bounds = tankBounds;
    const defaultGround = -tankBounds.y / 2 + 0.35;
    this.targetGroundLevel = defaultGround;
    this.currentGroundLevel = defaultGround;

    this.textureLoader = new THREE.TextureLoader();
    this.eyeIrisMaterial = new THREE.MeshBasicMaterial({ color: 0x734d14 });
    this.pupilMaterial = new THREE.MeshBasicMaterial({ color: 0x010101 });

    this.initLoader();
  }

  private initLoader() {
    const dracoLoader = new DRACOLoader();
    dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');
    this.loader = new GLTFLoader();
    this.loader.setDRACOLoader(dracoLoader);
  }

  public updateGroundLevel(newGroundY: number) {
    this.targetGroundLevel = newGroundY + 0.25;
  }

  public resetGroundLevel() {
    const defaultGround = -this.bounds.y / 2 + 0.35;
    this.targetGroundLevel = defaultGround;
    this.currentGroundLevel = defaultGround;
    
    for (const fish of this.fishList) {
      if (fish.config.behavior === 'bottom_dweller') {
        fish.preferredDepth = defaultGround;
        fish.model.position.y = defaultGround;
      }
    }
  }

  // Belirli bir türden 1 adet ekler
  public addSingleFish(config: FishConfig) {
    if (this.templates.has(config.id)) {
      this.spawnFish(this.templates.get(config.id)!, 1);
      return;
    }
    this.loadAndSpawn(config, 1);
  }

  // Belirli bir türden 1 adet çıkarır
  public removeSingleFish(configId: string): boolean {
    const index = this.fishList.findIndex(f => f.config.id === configId);
    if (index !== -1) {
      const fish = this.fishList.splice(index, 1)[0];
      this.scene.remove(fish.model);
      return true;
    }
    return false;
  }

  // Belirli bir türün tamamını siler
  public removeSpecies(configId: string) {
    const remaining = this.fishList.filter(f => f.config.id !== configId);
    const toRemove = this.fishList.filter(f => f.config.id === configId);
    toRemove.forEach(f => this.scene.remove(f.model));
    this.fishList = remaining;
  }

  public clearAllFish() {
    while (this.fishList.length > 0) {
      const fish = this.fishList.pop();
      if (fish) this.scene.remove(fish.model);
    }
  }

  private loadAndSpawn(config: FishConfig, count: number) {
    const colorHex = config.appearance?.color || '#8c928d';
    const fallbackMaterial = new THREE.MeshBasicMaterial({ color: new THREE.Color(colorHex), side: THREE.DoubleSide });

    if (config.texturePath) {
      this.textureLoader.load(
        config.texturePath,
        (texture) => {
          texture.colorSpace = THREE.SRGBColorSpace;
          texture.wrapS = THREE.RepeatWrapping;
          texture.wrapT = THREE.RepeatWrapping;
          texture.needsUpdate = true;
          const texMaterial = new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide });
          this.loadModelGLTF(config, texMaterial, count);
        },
        undefined,
        () => this.loadModelGLTF(config, fallbackMaterial, count)
      );
    } else {
      this.loadModelGLTF(config, fallbackMaterial, count);
    }
  }

  private loadModelGLTF(config: FishConfig, material: THREE.Material, count: number) {
    this.loader.load(
      config.modelPath,
      (gltf) => {
        const model = gltf.scene;
        model.traverse((child) => {
          if ((child as THREE.Mesh).isMesh) {
            const mesh = child as THREE.Mesh;
            const geometry = mesh.geometry;
            const lowerName = mesh.name.toLowerCase();

            if (!geometry.attributes.uv) {
              const pos = geometry.attributes.position;
              const uvs = [];
              for (let i = 0; i < pos.count; i++) {
                const x = pos.getX(i);
                const z = pos.getZ(i);
                const u = (Math.atan2(z, x) / Math.PI + 1) * 0.5;
                const v = (pos.getY(i) + 1) * 0.5;
                uvs.push(u, v);
              }
              geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
            }

            if (lowerName.includes('pupil')) {
              mesh.material = this.pupilMaterial;
            } else if (lowerName.includes('eye')) {
              mesh.material = this.eyeIrisMaterial;
            } else {
              mesh.material = material;
            }
          }
        });

        const template: LoadedTemplate = { model, config };
        this.templates.set(config.id, template);
        this.spawnFish(template, count);
      },
      undefined,
      (err) => console.error(`Model yüklenemedi: ${config.modelPath}`, err)
    );
  }

  private spawnFish(template: LoadedTemplate, count: number) {
    const { model, config } = template;
    const margin = 0.8;
    const maxX = this.bounds.x / 2 - margin;
    const maxY = this.bounds.y / 2 - margin;
    const maxZ = this.bounds.z / 2 - margin;

    for (let c = 0; c < count; c++) {
      const fishClone = SkeletonUtils.clone(model);

      let tail: THREE.Object3D | undefined;
      let finLBig: THREE.Object3D | undefined;
      let finRBig: THREE.Object3D | undefined;

      fishClone.traverse((child) => {
        const n = child.name.toLowerCase();
        if (n.includes('tail')) tail = child;
        if (n.includes('fin_l_big') || (n.includes('fin') && n.includes('l') && n.includes('big'))) finLBig = child;
        if (n.includes('fin_r_big') || (n.includes('fin') && n.includes('r') && n.includes('big'))) finRBig = child;
      });

      const isBottomDweller = config.behavior === 'bottom_dweller';
      const initialY = isBottomDweller ? this.currentGroundLevel : THREE.MathUtils.randFloat(-maxY * 0.4, maxY * 0.4);

      fishClone.position.set(
        THREE.MathUtils.randFloat(-maxX + 0.5, maxX - 0.5),
        initialY,
        THREE.MathUtils.randFloat(-maxZ + 0.5, maxZ - 0.5)
      );

      const speed = THREE.MathUtils.randFloat(config.physics.minSpeed, config.physics.maxSpeed);
      const velocity = new THREE.Vector3(
        THREE.MathUtils.randFloatSpread(1),
        isBottomDweller ? 0 : THREE.MathUtils.randFloatSpread(0.02),
        THREE.MathUtils.randFloatSpread(1)
      ).normalize().multiplyScalar(speed);

      this.scene.add(fishClone);

      this.fishList.push({
        model: fishClone,
        velocity,
        targetVelocity: velocity.clone(),
        speed,
        config,
        preferredDepth: initialY,
        timer: Math.random() * config.physics.diveInterval,
        tail,
        finLBig,
        finRBig
      });
    }
  }

  public getFishCounts(): Record<string, number> {
    const counts: Record<string, number> = {};
    for (const f of this.fishList) {
      counts[f.config.id] = (counts[f.config.id] || 0) + 1;
    }
    return counts;
  }

  public update(elapsedTime: number) {
    this.currentGroundLevel = THREE.MathUtils.lerp(this.currentGroundLevel, this.targetGroundLevel, 0.08);

    const margin = 0.6;
    const minX = -this.bounds.x / 2 + margin;
    const maxX = this.bounds.x / 2 - margin;
    const minY = -this.bounds.y / 2 + margin;
    const maxY = this.bounds.y / 2 - margin;
    const minZ = -this.bounds.z / 2 + margin;
    const maxZ = this.bounds.z / 2 - margin;

    for (let i = 0; i < this.fishList.length; i++) {
      const fish = this.fishList[i];
      const cycle = elapsedTime * 8.0 + (i * 1.2);
      
      if (fish.tail) fish.tail.rotation.y = Math.sin(cycle) * 0.4;
      if (fish.finLBig) fish.finLBig.rotation.z = Math.cos(cycle) * 0.3;
      if (fish.finRBig) fish.finRBig.rotation.z = -Math.cos(cycle) * 0.3;

      const pos = fish.model.position;
      const phys = fish.config.physics;
      const isBottomDweller = fish.config.behavior === 'bottom_dweller';

      if (isBottomDweller) {
        fish.preferredDepth = this.currentGroundLevel;
        fish.targetVelocity.y = (this.currentGroundLevel - pos.y) * 0.15;
      } else {
        fish.timer++;
        if (fish.timer > phys.diveInterval) {
          fish.preferredDepth = THREE.MathUtils.randFloat(minY + 0.3, maxY - 0.3);
          fish.timer = 0;
        }
        const depthDiff = fish.preferredDepth - pos.y;
        fish.targetVelocity.y = depthDiff * phys.verticalFreedom;
      }

      if (Math.random() < 0.015) {
        fish.targetVelocity.x += THREE.MathUtils.randFloatSpread(0.01);
        fish.targetVelocity.z += THREE.MathUtils.randFloatSpread(0.01);
      }

      const buffer = 1.3;
      const steer = 0.003;

      if (pos.x > maxX - buffer) fish.targetVelocity.x -= steer;
      if (pos.x < minX + buffer) fish.targetVelocity.x += steer;

      if (!isBottomDweller) {
        if (pos.y > maxY - buffer) fish.targetVelocity.y -= steer;
        if (pos.y < minY + buffer) fish.targetVelocity.y += steer;
      }

      if (pos.z > maxZ - buffer) fish.targetVelocity.z -= steer;
      if (pos.z < minZ + buffer) fish.targetVelocity.z += steer;

      fish.velocity.lerp(fish.targetVelocity, phys.turnSpeed);
      fish.velocity.clampLength(fish.speed * 0.5, fish.speed * 1.2);

      pos.add(fish.velocity);

      if (pos.x > maxX) { pos.x = maxX; fish.velocity.x *= -0.2; }
      if (pos.x < minX) { pos.x = minX; fish.velocity.x *= -0.2; }

      if (isBottomDweller) {
        pos.y = THREE.MathUtils.lerp(pos.y, this.currentGroundLevel, 0.2);
      } else {
        if (pos.y > maxY) { pos.y = maxY; fish.velocity.y *= -0.2; }
        if (pos.y < minY) { pos.y = minY; fish.velocity.y *= -0.2; }
      }

      if (pos.z > maxZ) { pos.z = maxZ; fish.velocity.z *= -0.2; }
      if (pos.z < minZ) { pos.z = minZ; fish.velocity.z *= -0.2; }

      if (fish.velocity.lengthSq() > 0.00001) {
        const targetPos = pos.clone().add(fish.velocity);
        if (isBottomDweller) targetPos.y = pos.y;
        
        const currentQuaternion = fish.model.quaternion.clone();
        fish.model.lookAt(targetPos);
        const targetQuaternion = fish.model.quaternion.clone();
        fish.model.quaternion.slerpQuaternions(currentQuaternion, targetQuaternion, 0.15);
      }
    }
  }
}